// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract CustomToken {
    string public name = "CustomToken";
    string public symbol = "CTK";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    address public owner;
    uint256 public taxFee = 5; // 5% transaction fee
    bool public paused = false;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) private blacklisted;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Blacklisted(address indexed account, bool status);
    event Paused(bool status);
    event TaxFeeUpdated(uint256 newFee);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not contract owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Token transfers are paused");
        _;
    }

    constructor() {
        owner = msg.sender;
        _mint(owner, 1000000 * (10 ** uint256(decimals))); // Mint 1M tokens to owner
    }

    function transfer(address _to, uint256 _value) public whenNotPaused returns (bool success) {
        require(!blacklisted[msg.sender], "Sender is blacklisted");
        require(!blacklisted[_to], "Recipient is blacklisted");
        require(balanceOf[msg.sender] >= _value, "Insufficient balance");

        uint256 fee = (_value * taxFee) / 100;
        uint256 amountAfterFee = _value - fee;

        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += amountAfterFee;
        balanceOf[owner] += fee; // Send fee to owner

        emit Transfer(msg.sender, _to, amountAfterFee);
        emit Transfer(msg.sender, owner, fee);
        return true;
    }

    function approve(address _spender, uint256 _value) public returns (bool success) {
        allowance[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);
        return true;
    }

    function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns (bool success) {
        require(!blacklisted[_from], "Sender is blacklisted");
        require(!blacklisted[_to], "Recipient is blacklisted");
        require(balanceOf[_from] >= _value, "Insufficient balance");
        require(allowance[_from][msg.sender] >= _value, "Allowance exceeded");

        uint256 fee = (_value * taxFee) / 100;
        uint256 amountAfterFee = _value - fee;

        balanceOf[_from] -= _value;
        balanceOf[_to] += amountAfterFee;
        balanceOf[owner] += fee;
        allowance[_from][msg.sender] -= _value;

        emit Transfer(_from, _to, amountAfterFee);
        emit Transfer(_from, owner, fee);
        return true;
    }

    function _mint(address _to, uint256 _amount) internal {
        totalSupply += _amount;
        balanceOf[_to] += _amount;
        emit Transfer(address(0), _to, _amount);
    }

    function burn(uint256 _amount) public {
        require(balanceOf[msg.sender] >= _amount, "Insufficient balance");
        balanceOf[msg.sender] -= _amount;
        totalSupply -= _amount;
        emit Transfer(msg.sender, address(0), _amount);
    }

    function blacklist(address _account, bool _status) public onlyOwner {
        blacklisted[_account] = _status;
        emit Blacklisted(_account, _status);
    }

    function setTaxFee(uint256 _newFee) public onlyOwner {
        require(_newFee <= 10, "Fee cannot exceed 10%");
        taxFee = _newFee;
        emit TaxFeeUpdated(_newFee);
    }

    function pause() public onlyOwner {
        paused = true;
        emit Paused(true);
    }

    function unpause() public onlyOwner {
        paused = false;
        emit Paused(false);
    }
}
